-- ---------------------------------------------------------------------------
-- mod-warcrafted-teleport - datos base
--
-- NPC transportador con menú de destinos: capitales, mazmorras clásicas, TBC
-- y WotLK, raids y zonas del mundo. Restringido solo por nivel y facción.
-- Válido tanto para AzerothCore sin mods extra como con Playerbots activo:
-- ninguno de los dos cambia qué destinos deben estar disponibles.
--
-- El bloqueo por tier de mod-individual-progression NO está aquí: lo evalúa el
-- script del módulo por jugador cada vez que abre el menú (ver
-- src/mod_warcrafted_teleport.cpp). Las condiciones de este archivo son solo de
-- nivel y facción.
-- ---------------------------------------------------------------------------

SET
@ENTRY  := 190000,
@GUID  := 15000000;

-- Versiones anteriores del módulo escribían el bloqueo por tier como filas
-- CONDITION_QUESTREWARDED (tipo 8) sobre estos menús. Ya no se usan y hay que
-- retirarlas, o seguirían ocultando destinos aunque el bloqueo esté desactivado.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 15 AND `SourceGroup` BETWEEN 51900 AND 51908 AND `ConditionTypeOrReference` = 8;

DELETE FROM creature_template WHERE `entry`=@ENTRY LIMIT 1;
DELETE FROM creature_template_model WHERE `CreatureID`=@ENTRY;





-- Destinos del menú. El script del módulo (src/mod_warcrafted_teleport.cpp) los lee al
-- arrancar y resuelve cada opción por (menu_id, option_id). Antes esto vivía en
-- `smart_scripts`, pero SmartAI teletransporta antes de que ningún hook pueda cobrar,
-- comprobar cooldown ni saltarse el bloqueo para un GM.
CREATE TABLE IF NOT EXISTS `mod_warcrafted_teleport_destinations` (
  `menu_id` INT UNSIGNED NOT NULL,
  `option_id` INT UNSIGNED NOT NULL,
  `map` INT UNSIGNED NOT NULL,
  `position_x` FLOAT NOT NULL DEFAULT 0,
  `position_y` FLOAT NOT NULL DEFAULT 0,
  `position_z` FLOAT NOT NULL DEFAULT 0,
  `orientation` FLOAT NOT NULL DEFAULT 0,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`menu_id`, `option_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `mod_warcrafted_teleport_destinations`;

